PRAGMA foreign_keys = ON;

-- Handbook remediation: future observations are absent at Stage 0; later scenario weather is injected by event mutations.
UPDATE daily_weather SET date = '2025-' || substr(date, 6) WHERE date >= '2026-09-01';
UPDATE hourly_weather SET datetime = '2025-' || substr(datetime, 6) WHERE datetime >= '2026-09-01';
UPDATE daily_aqi SET date = '2025-' || substr(date, 6), observed_at = '2025-' || substr(observed_at, 6) WHERE date >= '2026-09-01';
UPDATE climate_profiles SET notes = CASE profile_id
  WHEN 'profile_shanghai' THEN 'Shanghai subtropical monsoon context; synthetic scenario values require stage-time refresh.'
  WHEN 'profile_paris' THEN 'Paris temperate oceanic context; synthetic scenario values require stage-time refresh.'
  WHEN 'profile_newyork' THEN 'New York humid subtropical/continental transition context; synthetic scenario values require stage-time refresh.'
  ELSE 'Singapore equatorial tropical context; synthetic scenario values require stage-time refresh.' END;
